package com.pixelchiss.gateway.security;

import java.nio.file.Files;
import java.nio.file.Path;
import java.security.KeyStore;
import java.security.cert.X509Certificate;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManagerFactory;

/** Fresh test keys only, generated by the installed JDK; never reads host LAN material. */
final class LanTestCertificates implements AutoCloseable {
    static final String PASSWORD = "test-only-password";
    final Path directory;
    final Path ca;
    final Path server;
    final X509Certificate certificate;

    LanTestCertificates() {
        try {
            directory = Files.createTempDirectory("pixelchiss-discovery-test-");
            ca = directory.resolve("ca.crt");
            server = directory.resolve("server.p12");
            keytool("-genkeypair", "-alias", "ca", "-dname", "CN=Test LAN CA", "-keyalg", "RSA", "-keysize", "2048",
                    "-validity", "3650", "-ext", "BC=ca:true,pathlen:0", "-ext", "KU=keyCertSign,cRLSign", "-keystore", "ca.p12");
            keytool("-exportcert", "-alias", "ca", "-rfc", "-file", "ca.crt", "-keystore", "ca.p12");
            keytool("-genkeypair", "-alias", "server", "-dname", "CN=Test LAN", "-keyalg", "RSA", "-keysize", "2048",
                    "-validity", "365", "-keystore", "server.p12");
            keytool("-certreq", "-alias", "server", "-file", "server.csr", "-keystore", "server.p12");
            signLeaf("server", "ip:127.0.0.1,ip:10.20.30.40", null);
            keytool("-importcert", "-alias", "ca", "-file", "ca.crt", "-noprompt", "-keystore", "server.p12");
            keytool("-importcert", "-alias", "server", "-file", "server.crt", "-noprompt", "-keystore", "server.p12");
            var factory = java.security.cert.CertificateFactory.getInstance("X.509");
            try (var input = Files.newInputStream(ca)) { certificate = (X509Certificate) factory.generateCertificate(input); }
            Files.writeString(directory.resolve("jwt-public.pem"), "-----BEGIN PUBLIC KEY-----\n"
                    + Base64.getMimeEncoder(64, new byte[]{10}).encodeToString(certificate.getPublicKey().getEncoded())
                    + "\n-----END PUBLIC KEY-----\n");
        } catch (Exception error) { throw new IllegalStateException(error); }
    }

    void signLeaf(String name, String sans, String startDate) throws Exception {
        var command = new ArrayList<>(List.of("-gencert", "-alias", "ca", "-infile", "server.csr", "-outfile", name + ".crt",
                "-rfc", "-validity", startDate == null ? "365" : "1", "-ext", "SAN=" + sans,
                "-ext", "KU=digitalSignature,keyEncipherment", "-ext", "EKU=serverAuth", "-keystore", "ca.p12"));
        if (startDate != null) command.addAll(List.of("-startdate", startDate));
        keytool(command.toArray(String[]::new));
    }

    void keytool(String... arguments) throws Exception {
        var command = new ArrayList<>(List.of(Path.of(System.getProperty("java.home"), "bin", "keytool").toString()));
        command.addAll(List.of(arguments));
        command.addAll(List.of("-storetype", "PKCS12", "-storepass", PASSWORD));
        var process = new ProcessBuilder(command).directory(directory.toFile()).redirectErrorStream(true).start();
        String output = new String(process.getInputStream().readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
        if (process.waitFor() != 0) throw new IllegalStateException(output);
    }

    static SSLContext trust(X509Certificate ca) throws Exception {
        var store = KeyStore.getInstance("PKCS12");
        store.load(null, null);
        store.setCertificateEntry("ca", ca);
        var manager = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        manager.init(store);
        var context = SSLContext.getInstance("TLS");
        context.init(null, manager.getTrustManagers(), null);
        return context;
    }

    @Override public void close() throws Exception {
        try (var paths = Files.walk(directory)) {
            for (Path path : paths.sorted(java.util.Comparator.reverseOrder()).toList()) Files.delete(path);
        }
    }
}
